import{_ as e,o as a,c as i,a2 as t}from"./chunks/framework.Ddyno5UB.js";const u=JSON.parse('{"title":"1. Bash Basics","description":"","frontmatter":{},"headers":[],"relativePath":"shell/bash-basics.md","filePath":"shell/bash-basics.md"}'),n={name:"shell/bash-basics.md"};function o(h,s,l,d,r,c){return a(),i("div",null,[...s[0]||(s[0]=[t('<h1 id="_1-bash-basics" tabindex="-1">1. Bash Basics <a class="header-anchor" href="#_1-bash-basics" aria-label="Permalink to &quot;1. Bash Basics&quot;">​</a></h1><p>Understanding the fundamentals of Bash (Bourne Again SHell) is critical for system administration, DevOps, and general automation.</p><h2 id="the-shebang" tabindex="-1">The Shebang (<code>#!</code>) <a class="header-anchor" href="#the-shebang" aria-label="Permalink to &quot;The Shebang (`#!`)&quot;">​</a></h2><p>Every shell script should begin with a shebang. This tells the operating system which interpreter to use to execute the file.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">#!/bin/bash</span></span></code></pre></div><p>While <code>#!/bin/sh</code> is also common, it defaults to the system&#39;s POSIX-compliant shell (often <code>dash</code> on Ubuntu), which lacks many advanced features of Bash. If you use Bash features, explicitly use <code>#!/bin/bash</code> or <code>#!/usr/bin/env bash</code>.</p><h2 id="executing-scripts" tabindex="-1">Executing Scripts <a class="header-anchor" href="#executing-scripts" aria-label="Permalink to &quot;Executing Scripts&quot;">​</a></h2><p>To execute a script, it must first be marked as executable.</p><ol><li><strong>Make it executable:</strong><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">chmod</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> +x</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my_script.sh</span></span></code></pre></div></li><li><strong>Run it:</strong><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./my_script.sh</span></span></code></pre></div></li></ol><p><em>(Note: The <code>./</code> specifies that the file is in the current directory. Without it, the shell only looks in the directories listed in your <code>$PATH</code>.)</em></p><h2 id="standard-streams-and-redirection" tabindex="-1">Standard Streams and Redirection <a class="header-anchor" href="#standard-streams-and-redirection" aria-label="Permalink to &quot;Standard Streams and Redirection&quot;">​</a></h2><p>Every command in Linux has three default data streams:</p><ol><li><strong>Standard Input (<code>stdin</code> - 0)</strong>: Where data is read from (defaults to keyboard).</li><li><strong>Standard Output (<code>stdout</code> - 1)</strong>: Where normal output goes (defaults to screen).</li><li><strong>Standard Error (<code>stderr</code> - 2)</strong>: Where error messages go (defaults to screen).</li></ol><h3 id="redirection-operators" tabindex="-1">Redirection Operators <a class="header-anchor" href="#redirection-operators" aria-label="Permalink to &quot;Redirection Operators&quot;">​</a></h3><p>You can redirect these streams using operators:</p><ul><li><code>&gt;</code> : Redirect standard output to a file (overwrites).<div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">echo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Hello World&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> output.txt</span></span></code></pre></div></li><li><code>&gt;&gt;</code> : Append standard output to a file.<div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">echo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Another line&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &gt;&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> output.txt</span></span></code></pre></div></li><li><code>2&gt;</code> : Redirect standard error to a file.<div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ls</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /nonexistent_directory</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> 2&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> errors.log</span></span></code></pre></div></li><li><code>&amp;&gt;</code> or <code>&gt; file 2&gt;&amp;1</code> : Redirect BOTH output and error to the same file.<div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./my_script.sh</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> combined_output.log</span></span></code></pre></div></li></ul><h2 id="exit-codes" tabindex="-1">Exit Codes <a class="header-anchor" href="#exit-codes" aria-label="Permalink to &quot;Exit Codes&quot;">​</a></h2><p>When a command finishes, it returns an integer called an exit status (or exit code).</p><ul><li><code>0</code> means <strong>Success</strong>.</li><li><code>1-255</code> means <strong>Failure</strong> (different numbers can indicate different types of errors).</li></ul><p>You can check the exit status of the <em>last run command</em> using the special variable <code>$?</code>.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ls</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /tmp</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">echo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;The command exited with: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">$?</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span></span></code></pre></div>',21)])])}const g=e(n,[["render",o]]);export{u as __pageData,g as default};
